# Test hypothesis: if a cell shares row or column with any original 0, it becomes 0

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find original 0s
    zeros = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                zeros.add((r, c))

    # Find all rows and cols that contain a 0
    zero_rows = {r for (r, c) in zeros}
    zero_cols = {c for (r, c) in zeros}

    # Create output
    output = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r in zero_rows or c in zero_cols:
                output[r][c] = 0

    return output

