# Check diagonal adjacency hypothesis
def diagonal_neighbors(r, c, h, w):
    """Return diagonally adjacent cells"""
    for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w:
            yield (nr, nc)

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find original 0s
    zero_positions = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                zero_positions.add((r, c))

    # Output grid - start with fresh copy
    output = [[0]*w for _ in range(h)]

    # Mark original 0s
    for (r, c) in zero_positions:
        output[r][c] = 0

    # Mark diagonally adjacent cells as 0
    for (r, c) in zero_positions:
        for nr, nc in diagonal_neighbors(r, c, h, w):
            if output[nr][nc] != 0:  # Don't overwrite already 0
                output[nr][nc] = 0

    return output

